<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Requests\{CreateServiceRequest,UpdateServiceRequest};use App\Models\Service;use App\Services\ServiceManagementService;use Illuminate\Http\Request;class ServiceController extends ApiController{public function __construct(private ServiceManagementService $service){}public function index(Request $r){return $this->success($this->service->publicList($r->all()));}public function show(Service $service){abort_unless($service->status==='ACTIVE',404);return $this->success($service->load(['category','media']));}public function store(CreateServiceRequest $r){$this->admin($r);return response()->json(['data'=>$this->service->create($r->validated(),$r->user()),'meta'=>[]],201);}public function update(UpdateServiceRequest $r,Service $service){$this->admin($r);return $this->success($this->service->update($service,$r->validated()));}public function destroy(Request $r,Service $service){$this->admin($r);$this->service->delete($service);return response()->noContent();}private function admin(Request $r){abort_unless($r->user()->roles()->whereIn('name',['ADMIN','SUPER_ADMIN'])->exists(),403);}}
